package com.jcsh3132.jeago;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import android.webkit.CookieManager;import org.json.JSONObject;import java.net.URL;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.UUID;import java.util.concurrent.*;import javax.net.ssl.HttpsURLConnection;import com.google.firebase.messaging.FirebaseMessaging;
final class LeavePush {
 static final String CHANNEL="leave_approval";static final ExecutorService WORK=Executors.newSingleThreadExecutor();private static long lastSync=0;
 static boolean permitted(Context c){return Build.VERSION.SDK_INT<33||c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED;}
 static JSONObject request(String path,JSONObject body)throws Exception{String cookie=CookieManager.getInstance().getCookie(NavigationPolicy.SITE);if(cookie==null)return new JSONObject();HttpsURLConnection c=(HttpsURLConnection)new URL("https://jeago.vercel.app/api/push"+path).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Cookie",cookie);c.setRequestProperty("Origin","https://jeago.vercel.app");try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();if(status==401||status==403)return new JSONObject();if(status!=200)throw new IOException("request failed");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[2048];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>16384)throw new IOException("too large");out.write(buf,0,n);}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}finally{c.disconnect();}}
 static void channel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,"연차 승인 요청",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("지정 승인자에게만 전달되는 연차 승인 알림");ch.enableVibration(true);c.getSystemService(NotificationManager.class).createNotificationChannel(ch);}}
 static void sync(Activity a){long now=System.currentTimeMillis();if(now-lastSync<15000)return;lastSync=now;WORK.execute(()->{try{JSONObject state=request("",null);int stage=state.optInt("stage",0);if(stage!=1&&stage!=2){clear(a);return;}if(!state.optBoolean("enabled"))return;channel(a);a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;if(Build.VERSION.SDK_INT>=33&&!permitted(a)){if(!a.getPreferences(0).getBoolean("pushAsked",false)){a.getPreferences(0).edit().putBoolean("pushAsked",true).apply();a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},73);}return;}FirebaseMessaging.getInstance().setAutoInitEnabled(true);FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->register(a,token));});}catch(Exception ignored){}});}
 static void register(Context c,String token){if(!permitted(c))return;WORK.execute(()->{try{JSONObject state=request("",null);int stage=state.optInt("stage",0);if(stage!=1&&stage!=2)return;android.content.SharedPreferences p=c.getSharedPreferences("leave-push",0);String installation=p.getString("installation",null);if(installation==null){installation=UUID.randomUUID().toString();p.edit().putString("installation",installation).apply();}JSONObject d=new JSONObject();d.put("installation",installation);d.put("token",token);JSONObject result=request("",d);if(result.optBoolean("ok"))p.edit().putBoolean("registered",true).apply();}catch(Exception ignored){}});}
 static void clear(Context c){android.content.SharedPreferences p=c.getSharedPreferences("leave-push",0);if(p.getBoolean("registered",false)){FirebaseMessaging.getInstance().setAutoInitEnabled(false);FirebaseMessaging.getInstance().deleteToken();p.edit().putBoolean("registered",false).remove("seen").apply();c.getSystemService(NotificationManager.class).cancelAll();}}
 static void receive(Context c,String id,int stage){if(!id.matches("[a-f0-9]{64}")||(stage!=1&&stage!=2)||!permitted(c))return;try{JSONObject allowed=request("?event="+id,null);if(!allowed.optBoolean("allowed"))return;android.content.SharedPreferences prefs=c.getSharedPreferences("leave-push",0);java.util.Set<String> seen=new java.util.HashSet<>(prefs.getStringSet("seen",java.util.Collections.emptySet()));if(seen.contains(id))return;channel(c);Intent intent=new Intent(c,MainActivity.class).putExtra("open_leave",true).setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent open=PendingIntent.getActivity(c,id.hashCode(),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);builder.setSmallIcon(R.drawable.ic_notification).setContentTitle(stage==1?"연차 1차 승인 요청":"연차 최종 승인 요청").setContentText("승인할 연차 신청이 있습니다. 눌러서 확인해주세요.").setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setCategory(Notification.CATEGORY_EVENT).setDefaults(Notification.DEFAULT_ALL);if(Build.VERSION.SDK_INT<26)builder.setPriority(Notification.PRIORITY_HIGH);c.getSystemService(NotificationManager.class).notify(id.hashCode(),builder.build());if(seen.size()>100)seen.clear();seen.add(id);prefs.edit().putStringSet("seen",seen).apply();}catch(Exception ignored){}}
 static void pageLoaded(Activity a){lastSync=0;sync(a);}
 static void permissionResult(Activity a){lastSync=0;sync(a);}
}
